INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 5, 'theory', 'Quiz: dynamic memory and data structures');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 0, 'What is wrong with the line v->data = realloc(v->data, n);?', '["If it fails, realloc returns NULL and the old block is lost — a leak", "Nothing: this is how it is written", "realloc cannot be called on the heap", "You must call free first"]', 0, 'The result of realloc is first put into a temporary variable, checked for NULL, and only then assigned to the working pointer — otherwise on failure the only address of the old block is lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 1, 'What happens when free(p) is called twice in a row on the same pointer?', '["Nothing: the second call is ignored", "The program returns NULL", "The block is correctly freed twice", "Undefined behavior: heap corruption"]', 3, 'Double free is an ownership error. Set the pointer to NULL after free (free(NULL) is safe) and follow the "one owner" rule.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 2, 'Why is appending to a dynamic array that doubles its capacity amortized O(1)?', '["Because realloc is instantaneous", "Because expensive copies are rare, and their total cost grows linearly with the number of appends", "Because the capacity does not grow", "Because the array is stored on the stack"]', 1, 'With capacities 1, 2, 4, 8, … all the copying adds up to about 2n operations for n appends — a constant per append on average.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 3, 'In what order does an in-order traversal of a binary search tree yield the keys?', '["In insertion order", "Descending", "Ascending", "In random order"]', 2, 'The traversal "left subtree — node — right subtree" in a search tree goes in ascending key order: all left keys are smaller than the node, all right keys are larger.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 4, 'What is AddressSanitizer (-fsanitize=address) for?', '["It speeds up the program", "It finds buffer overflows, use-after-free, and leaks", "It compresses memory", "It checks code style"]', 1, 'It inserts checks around memory accesses and reports the line of the error and the place of allocation; the leak detector works together with it.');
